SELECT ?z WHERE {
  ?z a brick:Zone .
  FILTER(?z IN (ref:Perimeter_ZN_2, ref:Perimeter_ZN_3, ref:Perimeter_ZN_4))
}

SELECT ?zone ?zl ?sensor ?slabel ?type WHERE {
  ?zone rdfs:label ?zl .
  FILTER(STR(?zl) IN ("Perimeter_ZN_2", "Perimeter_ZN_3", "Perimeter_ZN_4"))
  ?zone brick:hasPoint ?sensor .
  ?sensor rdfs:label ?slabel .
  OPTIONAL { ?sensor a ?type }
}

SELECT ?zone ?sensor ?slabel ?type ?tsid WHERE {
  VALUES ?zone {
    http://buildgraph.org/BG_small_office_2004_0000#Zone_F1_Z03
    http://buildgraph.org/BG_small_office_2004_0000#Zone_F1_Z04
    http://buildgraph.org/BG_small_office_2004_0000#Zone_F1_Z05
  }
  ?zone brick:hasPoint ?sensor .
  ?sensor rdfs:label ?slabel .
  OPTIONAL { ?sensor a ?type }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?slabel ?type ?tsid WHERE {
  http://buildgraph.org/BG_small_office_2004_0000#Zone_F1_Z03 brick:hasPoint ?sensor .
  ?sensor rdfs:label ?slabel .
  OPTIONAL { ?sensor a ?type }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?slabel ?type ?tsid WHERE {
  ?zone brick:hasPoint ?sensor .
  ?zone rdfs:label "Perimeter_ZN_2" .
  ?sensor rdfs:label ?slabel .
  OPTIONAL { ?sensor a ?type }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?slabel ?type ?loc ?locLabel WHERE {
  ?sensor rdfs:label ?slabel .
  ?sensor a ?type .
  ?sensor brick:hasLocation ?loc .
  OPTIONAL { ?loc rdfs:label ?locLabel }
}

