import csv
zones = {
 'Perimeter_ZN_2': '1b318110-05c1-54b3-8fea-315f5900b64a',
 'Perimeter_ZN_3': '1689d963-4d6f-57dc-8368-b7b6ce076ca4',
 'Perimeter_ZN_4': '1b3eb9e6-d753-5328-bf35-516ad86dafc4',
}
totals = {z:0.0 for z in zones}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        tid = row['timeseries_id']
        if tid in zones.values() and row['timestamp'].startswith('2018-10-04'):
            which = [z for z in zones if zones[z]==tid][0]
            try:
                v=float(row['value'])
            except:
                continue
            # power W * 1h
            totals[which]+= v*1.0
print(totals)
print(max(totals, key=totals.get))
